nui 1
profile Paper
profile Canvas
style Ink {
 width: 2px,
 color: #123456,
 for @Paper { width: 4px, lineType: dashed, color: #aabbcc, }
 for @Canvas { width: 3px, color: #334455, }
}
style Suppress { for @Paper { visible: false, } }
group G {
 point Origin = coordinate(x: 0, y: 0)
 line Edge [Ink] = segment(start: (5, 2), end: (22, 14))
 line Hidden [Suppress] = segment(start: (-19, 31), end: (43, -11))
}
layout L { place @G(at: (11, -7), scale: 2) }
svg S(layout: @L, profile: @Paper, margin: 0)

nui 1
style Ink { width: 2px, color: #123456, }
style Hidden { visible: false, }
group G {
 point Origin = coordinate(x: 0, y: 0)
 line A [Hidden] = segment(start: (5, 2), end: (245, 2))
 line B [Hidden] = segment(start: (245, 2), end: (245, 42))
 line Joined [Ink] = join(paths: [@A, @B], closed: false)
 text Caption = label(text: "Alpha\nBeta", anchor: (12, 18), size: 5, angle: 0)
}
layout L { place @G(at: (31, -23)) }
print P(layout: @L, paper: a4, orientation: portrait, overlap: 10)

