module Marks(width: number = 17) {
 for i in range(min: 0, max: 2, step: 1, showGenerated: true) {
  point Mark = coordinate(x: @width + @i * 7, y: -@i * 3)
 }
 point Hidden(visible: false) = coordinate(x: 91, y: -13)
 point Off(enabled: false) = coordinate(x: -99, y: 81)
}
instance Left = Marks()
instance Right = Marks(width: 32)
